def is_interleave(s1, s2, s3):
    if len(s1) + len(s2) != len(s3):
        return False

    def f(i, j):               # can s1[:i] and s2[:j] form s3[:i+j]?
        if i == 0 and j == 0:
            return True
        k = i + j - 1
        if i > 0 and s1[i - 1] == s3[k] and f(i - 1, j):
            return True
        return j > 0 and s2[j - 1] == s3[k] and f(i, j - 1)
    return f(len(s1), len(s2))

def is_interleave(s1, s2, s3):
    if len(s1) + len(s2) != len(s3):
        return False

    @cache
    def f(i, j):
        if i == 0 and j == 0:
            return True
        k = i + j - 1
        if i > 0 and s1[i - 1] == s3[k] and f(i - 1, j):
            return True
        return j > 0 and s2[j - 1] == s3[k] and f(i, j - 1)
    return f(len(s1), len(s2))

def is_interleave(s1, s2, s3):
    m, n = len(s1), len(s2)
    if m + n != len(s3):
        return False
    ok = [[False] * (n + 1) for _ in range(m + 1)]
    ok[0][0] = True
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 and j == 0:
                continue
            k = i + j - 1
            from_s1 = i > 0 and ok[i - 1][j] and s1[i - 1] == s3[k]
            from_s2 = j > 0 and ok[i][j - 1] and s2[j - 1] == s3[k]
            ok[i][j] = from_s1 or from_s2
    return ok[m][n]

def is_interleave(s1, s2, s3):
    m, n = len(s1), len(s2)
    if m + n != len(s3):
        return False
    ok = [False] * (n + 1)
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 and j == 0:
                ok[0] = True
            else:
                from_s1 = i > 0 and ok[j] and s1[i - 1] == s3[i + j - 1]
                from_s2 = j > 0 and ok[j - 1] and s2[j - 1] == s3[i + j - 1]
                ok[j] = from_s1 or from_s2
    return ok[n]
